sys_script_client.script:
/**
 * ESR - Category change clears subcategory
 *
 * Runs when Category changes on the Employee Issue Ticket form.
 *
 *  1. Clears any previously selected Subcategory, so a stale subcategory from
 *     a different category can never be carried over.
 *  2. Tells the user when the newly selected category has no active
 *     subcategories configured, instead of leaving them with a picker that
 *     silently returns nothing.
 *
 * The Subcategory picker itself is filtered by the field's reference
 * qualifier, which re-evaluates because `ref_qual_elements=category` is set on
 * the dictionary entry. This script handles the clearing and the messaging.
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Do not interfere with initial form rendering or template application.
    if (isLoading || isTemplate) {
        return
    }

    g_form.hideFieldMsg('subcategory', true)

    // Clear the stale subcategory whenever the category actually changes.
    if (oldValue !== newValue) {
        if (g_form.getValue('subcategory')) {
            g_form.setValue('subcategory', '')
        }
    }

    // No category selected - nothing further to report.
    if (!newValue) {
        return
    }

    // Ask the server how many active subcategories this category has.
    try {
        var ga = new GlideAjax('x_412993_employe_1.EsrSubcategoryAjax')
        ga.addParam('sysparm_name', 'getCategoryInfo')
        ga.addParam('sysparm_category', newValue)
        ga.getXMLAnswer(function (answer) {
            if (!answer) {
                return
            }

            var info
            try {
                info = JSON.parse(answer)
            } catch (e) {
                return
            }

            // Guard against a late response for a category the user has
            // already navigated away from.
            if (!info || info.category !== g_form.getValue('category')) {
                return
            }

            if (info.count === 0) {
                g_form.showFieldMsg(
                    'subcategory',
                    'No subcategories are currently available for the ' +
                        info.label +
                        ' category. You can leave Subcategory empty and submit the ticket.',
                    'info',
                    false
                )
            }
        })
    } catch (e) {
        // Never block the form because the lookup failed.
    }
}
